Lemma size_run (fx : FPState) R M (pc : Z) (W0 W1 W2 : bv 32) (b e len : Z) :
  fetch_word RSEGS (Z_to_bv 64 pc) = Some W0 -> is_ecall W0 = false -> decode_any W0 = Some (Op ALU_SUB 11 10 11, 4%Z) ->
  fetch_word RSEGS (Z_to_bv 64 (pc + 4)) = Some W1 -> is_ecall W1 = false -> decode_any W1 = Some (ShiftImm ALU_SRA 11 11 3, 4%Z) ->
  fetch_word RSEGS (Z_to_bv 64 (pc + 8)) = Some W2 -> is_ecall W2 = false -> decode_any W2 = Some (Mul M_MUL 11 11 12, 4%Z) ->
  0 <= pc -> pc + 12 < 2 ^ 64 ->
  getr R (reg 10) = Z_to_bv 64 e -> getr R (reg 11) = Z_to_bv 64 b -> getr R (reg 12) = Z_to_bv 64 INV3 ->
  e = b + 24 * len -> 0 <= len < 2 ^ 40 -> 0 <= b -> e < 2 ^ 64 ->
  exists R', msteps RSEGS (mst fx R pc M) (mst fx R' (pc + 12) M)
    /\ getr R' (reg 11) = Z_to_bv 64 len /\ (forall k, k <> 11%nat -> (k < 32)%nat -> getr R' (reg k) = getr R (reg k)).
Proof.
