(* [comment removed for export] *)
Definition adv (c : PQM.alvl) : PQM.alvl :=
  PQM.AL (PQM.lv_t c) (PQM.lv_k c) (if Z.eqb (PQM.lv_k c) 2 then 1 - PQM.lv_eo c else PQM.lv_eo c).
