Lemma xrest_frz M1 M2 (P : Z -> Prop) lvX kbx gx kbb1 sk1 b1 q1 cr Mh VM :
  hi_heap HI (aeown (AEST (stX lvX kbx gx) kbb1 en sk1) ++ LBX) cr Mh VM -> adaptor_at M1 oa ov (stX lvX kbx gx) ->
  mem_grows M1 M2 -> (forall i, 0 <= i < 2 ^ 64 -> ~ P i -> M2 (Z_to_bv 64 i) = M1 (Z_to_bv 64 i)) ->
  (forall a, P a -> S - 28672 <= a < S \/ oa + 48 <= a < oa + 96 \/ b <= a < b + 24 * 2 ^ k \/ in_block (PM.vs_own kbx) a) ->
  xinv M1 kbx kbb1 sk1 b1 q1 ->
  enc_at M2 ov osk en /\ sink_at M2 osk sk1 /\ ec_state M2 oec b1 cat /\ err_ok M2 q1
  /\ (forall B m, In (B, m) (enc_own en ++ NESK.sink_own sk1) -> 0 <= B /\ B + m <= 2 ^ 64 /\ L5C.agree_on M1 M2 B m).
Proof.
