(* [comment removed for export] *)
Lemma xinv_callee LBc sp' scr' W' M1 M2 kbx kbb1 sk1 b1 q1 :
  PMK.ek L LBc sp' scr' W' M1 M2 -> L5C.stk (hl_sptop L) M1 sp' scr' -> 0 <= scr' -> sp' <= S -> PMFR.brange L LBc ->
  (forall a, PMK.inW W' a -> oa + 72 <= a < oa + 96) ->
  (forall B m, In (B, m) (PM.vs_own kbx ++ enc_own en ++ NESK.sink_own sk1) -> In (B, m) LBc) ->
  kstr_at M1 (oa + 48) kbx ->
  xinv M1 kbx kbb1 sk1 b1 q1 -> xinv M2 kbx kbb1 sk1 b1 q1.
