Lemma xinv_pb (M M' : word -> option byte) (sp' : Z) (kb1 kb2 : PM.vstr) (kbb1 : list Z) (ch : Z) (b1 q1 : bool) :
  sp' <= S ->
  (forall a m, sp' <= a -> a + m <= 2 ^ 64 -> (a + m <= oa + 48 \/ oa + 72 <= a) -> L5C.agree_on M M' a m) ->
  (forall B m, In (B, m) (PQM.lvec_own b k ++ PM.vs_own key ++ LBXe) -> L5C.agree_on M M' B m) ->
  (forall e, err_ok M e -> err_ok M' e) ->
  kcontent RSEGS M' (oa + 48) kb2 (kbb1 ++ [ch]) -> 0 <= ch < 128 ->
  xinv M kb1 kbb1 sk b1 q1 -> xinv M' kb2 (kbb1 ++ [ch]) sk b1 q1.
