(* [comment removed for export] *)
Lemma FIN (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (st' : aest) (b1 q1 : bool) (cr1 : credit) :
  getr R1 (reg 1) = Z_to_bv 64 r -> (forall x, In x PMK.cs_all -> getr R1 (reg x) = getr R0 (reg x)) ->
  ae_at M1 oa ov osk st' -> ae_ok st' -> ec_state M1 oec b1 cat -> PMST.base_ok RSEGS AD M1 -> err_ok M1 q1 ->
  (bf = true -> b1 = true) -> (ef = true -> q1 = true) -> PNV.step_pop st st' bf b1 ->
  cm M1 -> PMSP.credit_keep cr0 cr1 (pot_ae L st) (pot_ae L st') -> model_but_vm model0 model1 ->
  hi_heap HI (aeown st' ++ LBX) cr1 M1 (m_vmmaps model1) ->
