Lemma POPPED (M1 M2 : word -> option byte) (P : Z -> Prop) (lvq : list PQM.alvl) (kbx : PM.vstr) (gx : Z) (crx : credit) (VM : VmMaps) :
  adaptor_at M1 oa ov (stX (lv0 ++ [c1]) kbx gx) -> saves M1 -> cme M1 -> world M1 ->
  hi_heap HI (PQM.aown (stX lvq kbx gx) ++ LBXe) crx M1 VM ->
  mem_grows M1 M2 -> (forall i, 0 <= i < 2 ^ 64 -> ~ P i -> M2 (Z_to_bv 64 i) = M1 (Z_to_bv 64 i)) ->
  (forall a, P a -> (oa + 80 <= a < oa + 88) \/ (S - 80 <= a < S - 48)) ->
  L5.u64_at RSEGS M2 (oa + 80) (e0 - 24) ->
  adaptor_at M2 oa ov (stX (lv00 ++ [c0]) kbx gx) /\ saves M2 /\ cme M2 /\ world M2.
Proof.
