Lemma KCALL (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (kb1 : PM.vstr) (g1 : Z) (kbb1 : list Z) (b1 q1 : bool) (cr : credit) :
  PQM.lv_t c1 = 1 ->
  getr R (reg 1) = Z_to_bv 64 0x3aee8 -> getr R (reg 2) = Z_to_bv 64 (S - 80) -> getr R (reg 8) = Z_to_bv 64 oa -> getr R (reg 10) = Z_to_bv 64 ov ->
  getr R (reg 11) = Z_to_bv 64 (S - 72) -> getr R (reg 13) = Z_to_bv 64 oec -> getr R (reg 19) = Z_to_bv 64 (oa + 48) -> getr R (reg 20) = Z_to_bv 64 (oa + 49) -> kept0 R ->
  L5.u64_at RSEGS M (S - 72) (PM.vs_data (oa + 48) kb1) -> L5.u64_at RSEGS M (S - 64) (PM.vs_size kb1) ->
  saves M -> cm M -> world M -> adaptor_at M oa ov (stP c0 kb1 g1) -> PQM.ks_ok PQM.SMB kb1 g1 -> PM.vs_size kb1 = PM.vs_size kb + 1 ->
  xinv M kb1 kbb1 sk b1 q1 ->
  PMSP.credit_keep cr0 cr (PQM.pot_adaptor L ast) (PQM.pot_adaptor L (stP c0 kb1 g1)) -> model_but_vm model0 model ->
  hi_heap HI (PQM.aown (stP c0 kb1 g1) ++ LBXe) cr M (m_vmmaps model) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R (ne_key AE) M model) K.
Proof.
